// Generated by tools/build-act2.js from V2's Lovetalk, Family Ties, bonding scenes, Vision Machine memories and Walk with Joel.
const MEMORIES = [{"id":"ml1","kind":"lovetalk","group":"San & Joel","title":"A Small Thing, Never Said","icon":"💜","scenes":[{"speaker":"Narrator","text":"It comes up for no real reason, the fire between you doing most of the talking, the way it usually does when something true is about to surface."},{"speaker":"Joel","text":"\"I still check that you’re breathing,\" Joel admits, quiet, like he’s deciding whether to actually say it as he goes. \"Some nights. I do not tell you because it sounds like I do not trust the world to just let you stay. I do not, particularly. I trust you. The world, less so.\""},{"speaker":"San","text":"\"I do the same thing,\" you tell him, and something in his face eases at that, like he expected to be the only one carrying it. \"I just never said it out loud either.\""},{"speaker":"Joel","text":"\"Then we are both just checking,\" Joel says, and takes your hand like that settles something neither of you needed to make a bigger deal of than it already was."}],"theme":"theme-act2-fire","motifs":["embers","mirror"],"stage":1},{"id":"ml2","kind":"lovetalk","group":"San & Joel","title":"Something Light, For Once","icon":"😄","scenes":[{"speaker":"Narrator","text":"Not every evening needs to carry weight. This one, mercifully, does not."},{"speaker":"San","text":"\"If you had to fight one enemy we’ve faced with absolutely no weapon, just your bare hands, which one?\""},{"speaker":"Joel","text":"\"The Frost Queen,\" Joel says instantly, no hesitation. \"She dances. I would just ask her to dance instead. Problem solved.\""},{"speaker":"San","text":"\"That is not fighting her. That is negotiating.\""},{"speaker":"Joel","text":"\"I have never once lost a fight I successfully avoided,\" Joel says, entirely serious, and you laugh hard enough that Soel opens one eye to judge you both."}],"theme":"theme-act2-fire","motifs":["snow","leaves"],"stage":2},{"id":"ml3","kind":"lovetalk","group":"San & Joel","title":"The Fear He Finally Names","icon":"😰","scenes":[{"speaker":"Narrator","text":"This one takes longer to arrive. You can tell by the way he sits with it first, turning it over before he lets it out."},{"speaker":"Joel","text":"\"I am afraid, some days, that I am not actually enough of a reason to stay,\" Joel says, finally, not looking at you directly. \"Not compared to everything else you have already survived leaving behind.\""},{"speaker":"San","text":"\"You are not a reason I stay instead of something else,\" you tell him, careful, wanting to get this exactly right. \"You are not competing with anything. You are just where I actually want to be.\""},{"speaker":"Joel","text":"\"I needed to hear that said plainly,\" Joel admits. \"Not implied. Said.\""},{"speaker":"San","text":"\"Then I will keep saying it,\" you tell him, \"for as long as you need it said.\""}],"theme":"theme-act2-fire","motifs":["dawn","mend"],"stage":3},{"id":"ml4","kind":"lovetalk","group":"San & Joel","title":"Nothing That Needs Words","icon":"🤍","scenes":[{"speaker":"Narrator","text":"Some evenings do not need dialogue to be the whole point. This is one of them."},{"speaker":"Narrator","text":"He does not say anything when he sits down beside you. He just does — close, quiet, his shoulder against yours, the two of you watching whatever the fire is doing without needing to narrate it to each other."},{"speaker":"Narrator","text":"Soel claims the space between your feet, unbothered, the way he always has. Nobody moves for a long while. Nobody needs to."},{"speaker":"San","text":"\"This,\" you say, eventually, quiet, not really a full sentence. Joel understands it anyway. He always does, now."}],"theme":"theme-act2-fire","motifs":["embers","beam"],"stage":4},{"id":"ml5","kind":"lovetalk","group":"San & Joel","title":"Choosing You Again","icon":"💍","scenes":[{"speaker":"Narrator","text":"It is not a proposal. You have never needed the formality of one, not after everything else that already proved it. It is smaller than that, and somehow larger."},{"speaker":"Joel","text":"\"If I had to do all of it again,\" Joel says, watching you across the fire, \"the Breaking, all of it, every single hard year that got us here — I would still choose this. Choose you. I want you to actually know that, not just assume it.\""},{"speaker":"San","text":"\"I would too,\" you tell him, and mean it entirely, no hesitation left anywhere in it. \"Every part of it. Even the parts that hurt.\""},{"speaker":"Joel","text":"\"Even the parts that hurt,\" Joel repeats, soft, like it means something particular to hear you say that specific phrase. \"Good. Me too.\""}],"theme":"theme-act2-fire","motifs":["cracks","beam"],"stage":5},{"id":"ml6","kind":"lovetalk","group":"San & Joel","title":"The Rain and the Kitten, Still","icon":"🌧️","scenes":[{"speaker":"Narrator","text":"You find yourselves talking about it again, unprompted — the box, the rain, the small grey kitten neither of you had any real plan for. The very beginning, however far away it has since become."},{"speaker":"San","text":"\"I think about that box sometimes,\" you admit. \"How none of this — any of it — was supposed to start there. It just did.\""},{"speaker":"Joel","text":"\"I think about it too,\" Joel says. \"More than I probably should. It is strange, being able to point to one exact afternoon and say, that. That is where it actually started, even though neither of us knew it yet.\""},{"speaker":"San","text":"\"Soel knew,\" you say, glancing at the cat currently asleep against Joel’s leg, entirely unbothered by being discussed. \"I think he has always known.\""},{"speaker":"Joel","text":"\"He usually does,\" Joel agrees, and pulls you in, the fire and the rain-that-was and the whole long road between them somehow all present in the same quiet moment."}],"theme":"theme-act2-fire","motifs":["water","mobile"],"stage":6},{"id":"ml7","kind":"lovetalk","group":"San & Joel","title":"The Question the Codex Left Behind","icon":"👥","scenes":[{"speaker":"Narrator","text":"It resurfaces on its own, the way things like this do — not forced, just finally ready to be held properly instead of set aside."},{"speaker":"San","text":"\"I still think about them sometimes,\" you admit. \"The cottage. How tired they looked. I do not know why it stayed with me the way it did.\""},{"speaker":"Joel","text":"\"I think about it too,\" Joel says, honest. \"Not because I want to know more. Because some part of me is grateful, every time, that whatever happened to them did not happen to us.\""},{"speaker":"San","text":"\"We do not know that it did not,\" you say, gentle, not trying to unsettle him, just being accurate. \"We just know ours went differently.\""},{"speaker":"Joel","text":"\"Differently is enough for me,\" Joel says. \"I do not need the whole answer. I just need this version to keep being true.\""}],"theme":"theme-act2-fire","motifs":["clock","horizon"],"stage":7},{"id":"ml8","kind":"lovetalk","group":"San & Joel","title":"What the Library Actually Costs","icon":"📖","scenes":[{"speaker":"Narrator","text":"The weight of it lands properly some nights, well after the decision itself was already made."},{"speaker":"Joel","text":"\"Years,\" Joel says, quiet, watching the fire. \"Maybe decades. I said yes to that so easily, at the time. I do not think I let myself actually feel the size of it until just now.\""},{"speaker":"San","text":"\"I know,\" you tell him. \"I felt it too, late, the same way. It is a strange thing, choosing a timeline that outlasts how urgent it feels in the moment.\""},{"speaker":"Joel","text":"\"Do you regret it? Saying yes that fast?\""},{"speaker":"San","text":"\"No,\" you say, certain. \"I just needed to actually feel the weight of it before I could carry it properly. I think that is different from regret.\""}],"theme":"theme-act2-fire","motifs":["ledger","clock"],"stage":8},{"id":"ml9","kind":"lovetalk","group":"San & Joel","title":"Carrying It Together","icon":"🤝","scenes":[{"speaker":"Narrator","text":"This one is less a conversation than an agreement, arrived at slowly, over several quieter evenings before this one."},{"speaker":"Joel","text":"\"I do not want to just survive this timeline,\" Joel says. \"The years. I want to actually live through them with you, not just endure them side by side.\""},{"speaker":"San","text":"\"Then let us make sure we do that on purpose,\" you say. \"Not just Library work and waiting. Evenings like this too. On purpose, not by accident.\""},{"speaker":"Joel","text":"\"On purpose,\" Joel agrees, like it is a promise worth naming plainly rather than just assuming. \"I can do on purpose.\""}],"theme":"theme-act2-fire","motifs":["figures","clock"],"stage":9},{"id":"ml10","kind":"lovetalk","group":"San & Joel","title":"The Door He Never Closed","icon":"🚪","scenes":[{"speaker":"Narrator","text":"Neither of you brings it up often. Tonight, quietly, San does."},{"speaker":"San","text":"\"You said once you were not closing the door,\" you say, careful. \"On having a child of our own, someday. I think about that more than I say out loud.\""},{"speaker":"Joel","text":"\"I meant it,\" Joel says, simple. \"I still mean it. Not now — not with the Tower, the strongholds, everything we are already carrying. But not never, either.\""},{"speaker":"San","text":"\"Not never,\" you repeat, and something in the phrase settles rather than unsettles you. \"I can live inside that. I do not need it resolved tonight.\""},{"speaker":"Joel","text":"\"Then we will leave it exactly where it is,\" Joel says, gentle. \"Open. Ours. Whenever it is actually time.\""}],"theme":"theme-act2-fire","motifs":["doors","mobile"],"stage":10},{"id":"ml11","kind":"lovetalk","group":"San & Joel","title":"Whatever Comes, Together","icon":"⭐","scenes":[{"speaker":"Narrator","text":"The fire has burned low, and neither of you has moved to build it back up, content to let the evening end exactly as quietly as it started."},{"speaker":"Joel","text":"\"Years from now,\" Joel says, \"however this Library work actually ends — I do not need to know the ending yet. I just need to know I am still doing it with you when it comes.\""},{"speaker":"San","text":"\"You will be,\" you tell him, certain in a way that does not need proving anymore, only saying. \"Whatever it turns out to be. Together is the only version I am actually planning for.\""},{"speaker":"Joel","text":"\"Together,\" Joel says, and it lands like it always has, since a rainy porch in a life that does not exist anymore — simple, true, and entirely enough."}],"theme":"theme-act2-fire","motifs":["figures","embers"],"stage":11},{"id":"mf-aisyah1","kind":"family","group":"Aisyah","title":"The Ledger She Keeps Privately","icon":"🗡️","scenes":[{"speaker":"Narrator","text":"Aisyah finds you between fights, characteristically unceremonious about it."},{"speaker":"Aisyah","text":"\"I keep a list,\" she admits, offhand, like it costs her something to say even that plainly. \"Not written. Just — kept. Every time you actually needed me and I showed up anyway. It is longer than I expected it to get.\""},{"speaker":"San","text":"\"Why keep it at all?\""},{"speaker":"Aisyah","text":"\"Because I am not good at saying it the soft way,\" Aisyah says. \"This is the version I have instead.\""}],"theme":"theme-act2-none","motifs":["ledger","clock"],"who":"Aisyah","stage":1},{"id":"mf-aisyah2","kind":"family","group":"Aisyah","title":"Family Business, Reconsidered","icon":"📜","scenes":[{"speaker":"Aisyah","text":"\"Senedra wants to run the trade routes properly someday,\" Aisyah says, watching her daughter from across camp. \"I keep telling her family business should stay in the family. I am starting to understand that means something different now than it used to.\""},{"speaker":"San","text":"\"Different how?\""},{"speaker":"Aisyah","text":"\"Used to mean blood only,\" Aisyah says. \"Does not mean that anymore. Has not for a while, honestly. I just took longer than most of us to actually say so.\""}],"theme":"theme-act2-none","motifs":["figures","road"],"who":"Aisyah","stage":2},{"id":"mf-aisyah3","kind":"family","group":"Aisyah","title":"What She Does Not Dwell On","icon":"🌤️","scenes":[{"speaker":"San","text":"\"You never dwell on the hard parts,\" you say. \"I used to think that meant you had not really felt them.\""},{"speaker":"Aisyah","text":"\"I felt them,\" Aisyah says, plain, no defensiveness in it. \"I just decided a long time ago that dwelling never actually fixed anything for me. Moving forward did. Different people process differently. Neither way is more honest than the other.\""},{"speaker":"San","text":"\"I know that now,\" you tell her. \"I did not always.\""}],"theme":"theme-act2-none","motifs":["clock","dawn"],"who":"Aisyah","stage":3},{"id":"mf-aisyah4","kind":"family","group":"Aisyah","title":"The Sister She Actually Is","icon":"🌙","scenes":[{"speaker":"Narrator","text":"This one arrives without much preamble, the way the truest things with Aisyah usually do."},{"speaker":"Aisyah","text":"\"I do not say this enough,\" she says, uncharacteristically direct. \"You are the reason I still believe families can be chosen properly, not just survived. That is not a small thing. I do not hand that out for free.\""},{"speaker":"San","text":"\"I know exactly how rare that is, coming from you,\" you say, and mean every word of it."},{"speaker":"Aisyah","text":"\"Good,\" Aisyah says, already moving on before either of you can get too sentimental about it. \"Do not make me say it twice.\""}],"theme":"theme-act2-none","motifs":["candles","horizon"],"who":"Aisyah","stage":4},{"id":"mf-mezstorm1","kind":"family","group":"Mezstorm","title":"The Storm That Answers Now","icon":"⛈️","scenes":[{"speaker":"Mezstorm","text":"\"The lightning used to just happen to me,\" Mezstorm says, watching his own hands spark faintly, unbothered. \"Now it answers when I actually call it. I do not think I have said out loud how much that difference matters.\""},{"speaker":"San","text":"\"What changed?\""},{"speaker":"Mezstorm","text":"\"I stopped being afraid of what I could become,\" he says, \"and started being curious about it instead.\""}],"theme":"theme-act2-none","motifs":["storm","beam"],"who":"Mezstorm","stage":1},{"id":"mf-mezstorm2","kind":"family","group":"Mezstorm","title":"Eliz's Mum","icon":"💙","scenes":[{"speaker":"Mezstorm","text":"\"She still calls me Mum,\" Mezstorm says, quiet, watching Eliz from across the fire. \"Even like this. Especially like this. I do not think I will ever stop being surprised by that, honestly.\""},{"speaker":"San","text":"\"Why would you be surprised? You have earned it.\""},{"speaker":"Mezstorm","text":"\"Because I did not earn my first two,\" he says, and lets that sit, honest without needing to explain further."}],"theme":"theme-act2-none","motifs":["beam","embers"],"who":"Mezstorm","stage":2},{"id":"mf-mezstorm3","kind":"family","group":"Mezstorm","title":"What He Sends Now","icon":"💌","scenes":[{"speaker":"Mezstorm","text":"\"I used to think sending money was the same as being there,\" Mezstorm says. \"It is not. I know that now. But I still send what I can, when I can — not instead of being present. Alongside it.\""},{"speaker":"San","text":"\"That is different from before. Genuinely.\""},{"speaker":"Mezstorm","text":"\"It is the same gesture,\" he agrees, \"but it means something different when it is not the only thing you are offering.\""}],"theme":"theme-act2-none","motifs":["mirror","ledger"],"who":"Mezstorm","stage":3},{"id":"mf-mezstorm4","kind":"family","group":"Mezstorm","title":"Thawed, On Purpose","icon":"❄️","scenes":[{"speaker":"Narrator","text":"He finds you specifically for this one, which is rare enough on its own to notice."},{"speaker":"Mezstorm","text":"\"You did not give up on me,\" Mezstorm says, plain. \"When I was still frozen. When it would have been easier not to bother. I do not think I say thank you for that nearly often enough.\""},{"speaker":"San","text":"\"You do not have to keep thanking me,\" you tell him, gentle. \"You just have to keep thawing. That is thanks enough.\""},{"speaker":"Mezstorm","text":"\"Then I will keep doing that,\" he says, \"for as long as it takes.\""}],"theme":"theme-act2-none","motifs":["mend","snow"],"who":"Mezstorm","stage":4},{"id":"mf-eliz1","kind":"family","group":"Eliz","title":"Textures and Colors","icon":"✨","scenes":[{"speaker":"Eliz","text":"\"Your magic feels like warm static,\" Eliz says, matter-of-fact, the way she describes most things. \"Joel’s feels like a held breath. I like knowing what everyone feels like. It helps me understand who is actually safe.\""},{"speaker":"San","text":"\"What do I feel like when I am upset?\""},{"speaker":"Eliz","text":"\"Sharper,\" Eliz says, without hesitation. \"But never pointed at me. I have always known that much.\""}],"theme":"theme-act2-none","motifs":["phone","figures"],"who":"Eliz","stage":1},{"id":"mf-eliz2","kind":"family","group":"Eliz","title":"The Girl Who Endured","icon":"🌸","scenes":[{"speaker":"San","text":"\"You have always endured so much,\" you tell her, gentle. \"I do not think I say that enough.\""},{"speaker":"Eliz","text":"\"I do not think of it as enduring,\" Eliz says, considering it seriously, the way she considers most things. \"I think of it as just — staying. Staying is not the same as suffering, even when other people assume it must be.\""},{"speaker":"San","text":"\"That is a better way to think about it than I ever managed.\""}],"theme":"theme-act2-none","motifs":["mend","mirror"],"who":"Eliz","stage":2},{"id":"mf-eliz3","kind":"family","group":"Eliz","title":"Some Wounds Are Not of the Body","icon":"🕊️","scenes":[{"speaker":"Eliz","text":"\"I can mend bodies easily,\" Eliz says. \"The other wounds take longer. I am still learning those. I do not think anyone ever finishes learning those, honestly.\""},{"speaker":"San","text":"\"You have already helped with more of mine than you probably know.\""},{"speaker":"Eliz","text":"\"I know more than you think,\" Eliz says, small smile. \"I just do not always say so out loud.\""}],"theme":"theme-act2-none","motifs":["mend","dawn"],"who":"Eliz","stage":3},{"id":"mf-eliz4","kind":"family","group":"Eliz","title":"Guardian Spirit","icon":"🛡️","scenes":[{"speaker":"Narrator","text":"This one arrives quietly, Eliz’s hands finding yours the way they do before something honest."},{"speaker":"Eliz","text":"\"I cannot be reduced below one HP,\" Eliz says. \"Not because I am special. Because someone, somewhere, decided I had already survived enough. I try to be that for other people too, when I can.\""},{"speaker":"San","text":"\"You already are. For all of us.\""},{"speaker":"Eliz","text":"\"Good,\" Eliz says, satisfied, and squeezes your hand once before letting go."}],"theme":"theme-act2-none","motifs":["rings","horizon"],"who":"Eliz","stage":4},{"id":"mf-senedra1","kind":"family","group":"Senedra","title":"Paths Others See as Walls","icon":"🏹","scenes":[{"speaker":"Senedra","text":"\"I learned this from Mum,\" Senedra says, tracing a route on a map only she seems able to read clearly. \"Aisyah. Not just the tracking. The part where you keep looking even after everyone else has decided there is no path.\""},{"speaker":"San","text":"\"She is good at that.\""},{"speaker":"Senedra","text":"\"She is the best at that,\" Senedra says, certain, no hesitation in it at all."}],"theme":"theme-act2-none","motifs":["road","figures"],"who":"Senedra","stage":1},{"id":"mf-senedra2","kind":"family","group":"Senedra","title":"Dried Goods and Trade Routes","icon":"📦","scenes":[{"speaker":"Senedra","text":"\"The real money is in dried goods,\" Senedra says, entirely serious, offering you pemmican like it is a genuine business proposal. \"They travel. They last. They sell. I have thought about this a great deal.\""},{"speaker":"San","text":"\"You sound exactly like your mother.\""},{"speaker":"Senedra","text":"\"I have been told,\" Senedra says, pleased rather than annoyed by the comparison."}],"theme":"theme-act2-none","motifs":["ledger","road"],"who":"Senedra","stage":2},{"id":"mf-senedra3","kind":"family","group":"Senedra","title":"The Niece Who Grew Up Sharp","icon":"🎯","scenes":[{"speaker":"San","text":"\"You have grown up so much,\" you tell her, and mean it in the specific way you only get to mean it with someone you have actually watched grow."},{"speaker":"Senedra","text":"\"I had good examples,\" Senedra says. \"You. Mum. Eliz, even, in her own way. I do not think I could have turned out any other way, honestly, with all of you around.\""},{"speaker":"San","text":"\"That might be the nicest thing you have ever said to me.\""},{"speaker":"Senedra","text":"\"Do not let it go to your head,\" Senedra says, already smiling."}],"theme":"theme-act2-none","motifs":["beam","leaves"],"who":"Senedra","stage":3},{"id":"mf-senedra4","kind":"family","group":"Senedra","title":"Eagle-Eyed, On Purpose","icon":"🦅","scenes":[{"speaker":"Narrator","text":"She finds you at the edge of camp, watching something on the horizon only she can properly make out yet."},{"speaker":"Senedra","text":"\"I see the path before anyone else does,\" Senedra says. \"I used to think that made me useful. Now I think it just makes me yours — family, the kind that watches out ahead so nobody else has to worry about what is coming.\""},{"speaker":"San","text":"\"You have always been more than useful to me.\""},{"speaker":"Senedra","text":"\"I know,\" Senedra says, quiet certainty in it. \"I just like hearing it said.\""}],"theme":"theme-act2-none","motifs":["road","beam"],"who":"Senedra","stage":4},{"id":"mf-zaki1","kind":"family","group":"Zaki","title":"The Pack, Checked Again","icon":"🎒","scenes":[{"speaker":"Zaki","text":"\"Seventeen items,\" Zaki says, going through his pack for what is very obviously not the first time today. \"I have never once needed all seventeen. I have also never once dropped below seventeen. I do not examine that too closely.\""},{"speaker":"San","text":"\"It keeps you steady. That is not nothing.\""},{"speaker":"Zaki","text":"\"That is exactly what it does,\" Zaki agrees, relieved someone finally said it plainly instead of teasing him about it."}],"theme":"theme-act2-none","motifs":["dawn","clock"],"who":"Zaki","stage":1},{"id":"mf-zaki2","kind":"family","group":"Zaki","title":"The Cafe, Actually His","icon":"☕","scenes":[{"speaker":"Zaki","text":"\"I did not expect to be good at this,\" Zaki admits, wiping down his own counter with real, quiet pride. \"The planning, the logistics, the small talk. It turns out checking a pack seventeen times and running a whole cafe use the same muscle.\""},{"speaker":"San","text":"\"You built something real here.\""},{"speaker":"Zaki","text":"\"I did,\" Zaki says, and for once does not deflect the compliment at all."}],"theme":"theme-act2-none","motifs":["mirror","clock"],"who":"Zaki","stage":2},{"id":"mf-zaki3","kind":"family","group":"Zaki","title":"What Kyle Never Had","icon":"⚖️","scenes":[{"speaker":"Zaki","text":"\"I heard what you said about Kyle,\" Zaki admits, a little sheepish about it. \"I do not think I ever had to choose steady over impulsive. I just always was steady. I do not know if that makes it a virtue or just luck.\""},{"speaker":"San","text":"\"Maybe it does not need to be one or the other.\""},{"speaker":"Zaki","text":"\"Maybe not,\" Zaki agrees, considering it properly. \"Either way, I am glad it is who I turned out to be.\""}],"theme":"theme-act2-none","motifs":["rings","dawn"],"who":"Zaki","stage":3},{"id":"mf-zaki4","kind":"family","group":"Zaki","title":"The Nephew Who Grew Into It","icon":"🗡️","scenes":[{"speaker":"Narrator","text":"He finds you between his own shifts, still faintly smelling of coffee and ink from the ledgers."},{"speaker":"Zaki","text":"\"Mum says you’re the bravest person she knows,\" Zaki says. \"I think she is right. I also think you taught me most of what bravery is actually supposed to look like, even the boring parts. Especially the boring parts.\""},{"speaker":"San","text":"\"You have more than earned your own place in this, Zaki. Not just as family. As yourself.\""},{"speaker":"Zaki","text":"\"I know,\" Zaki says, quiet certainty under the usual easy grin. \"I just like hearing it said too.\""}],"theme":"theme-act2-none","motifs":["gears","ledger"],"who":"Zaki","stage":4},{"id":"mf-soel1","kind":"family","group":"Soel","title":"The Sunny Patch","icon":"☀️","scenes":[{"speaker":"Narrator","text":"Soel claims a patch of light on the floor with the unbothered certainty of a cat who has never once doubted his right to it."},{"speaker":"San","text":"\"You always find the good spot,\" you tell him, and he simply blinks, slow, unimpressed by the observation."},{"speaker":"Narrator","text":"It is, somehow, exactly the right amount of conversation for both of you."}],"theme":"theme-act2-none","motifs":["dawn","embers"],"who":"Soel","stage":1},{"id":"mf-soel2","kind":"family","group":"Soel","title":"A Leaf, Charred at the Edges","icon":"🍂","scenes":[{"speaker":"Narrator","text":"Soel brings you something again — a small, ordinary token, offered without ceremony, the way he always does."},{"speaker":"San","text":"\"Thank you,\" you tell him, taking it seriously, the way you have learned to take everything he offers seriously."},{"speaker":"Narrator","text":"He does not need the thanks. He gives it anyway, every time, unasked."}],"theme":"theme-act2-none","motifs":["embers","clock"],"who":"Soel","stage":2},{"id":"mf-soel3","kind":"family","group":"Soel","title":"Unkillable, Chosen Anyway","icon":"🐾","scenes":[{"speaker":"San","text":"\"You did not have to choose me,\" you tell him, quiet, scratching behind his ears the way he tolerates from exactly one person. \"You could have chosen anyone.\""},{"speaker":"Narrator","text":"Soel leans into your hand, unhurried, the specific weight of an answer that was never going to need more words than this."}],"theme":"theme-act2-none","motifs":["embers","leaves"],"who":"Soel","stage":3},{"id":"mf-soel4","kind":"family","group":"Soel","title":"The Space Between","icon":"💫","scenes":[{"speaker":"Narrator","text":"He sits between you and Joel tonight, deliberate about it, the way he has since a rainy porch in a life that does not exist anymore."},{"speaker":"San","text":"\"You are the space between us,\" you say, soft, understanding it freshly even after everything. \"You always have been.\""},{"speaker":"Narrator","text":"Soel does not confirm it. He never does. He just stays exactly where he is, warm and certain, and lets that be the whole answer."}],"theme":"theme-act2-none","motifs":["water","mobile"],"who":"Soel","stage":4},{"id":"mb-joel_san_date","kind":"bonding","group":"Joel","title":"Just the Two of You","icon":"💜","scenes":[{"speaker":"Narrator","text":"Joel asks, plainly, if you'd like to have dinner together. Not a tactical debrief. Not a rest-site check-in. Dinner. He says the word like it costs him something to say out loud, which, you realize, it probably does."},{"speaker":"Joel","text":"\"I know how this looks,\" he says, already half-regretting asking, in the specific way he regrets things that matter to him. \"Everyone else is resting. I just thought — we do not do this. Just this. Often enough.\""},{"speaker":"San","text":"\"We don't,\" you agree, and you are surprised by how much you want to. \"Let's do this.\""},{"speaker":"Narrator","text":"He finds someplace quiet — not romantic on purpose, just quiet, which turns out to be exactly right. He talks less than usual. You talk more than usual, to fill the space, and he lets you, watching you with the same steady attention he brings to a shield wall."},{"speaker":"Joel","text":"\"I asked to stand beside you while you found out why you were here,\" he says, eventually, turning his cup in his hands instead of looking at you directly. \"I do not think I ever asked if you wanted me beside you for the rest of it too. I am asking now.\""},{"speaker":"San","text":"\"You never had to ask that one,\" you say. \"But I am glad you did anyway.\""}],"theme":"theme-act2-water","motifs":["figures","mend"],"who":"Joel","minAffinity":150,"alt":[{"speaker":"Narrator","text":"Joel asks, plainly, if you'd like to have dinner together, just the two of you. Soel is draped over his shoulders before he finishes the sentence, purring like he was invited, which, as far as Soel is concerned, he was."},{"speaker":"Joel","text":"\"Just the two of us,\" Joel says again, to Soel specifically, without much hope. Soel does not move. Joel sighs the particular sigh of a man who has already lost this argument. \"Fine. The three of us.\""},{"speaker":"San","text":"You laugh, actually laugh, for the first time in a while. \"He chose us both. I do not think we get a vote.\""},{"speaker":"Narrator","text":"Dinner happens anyway, Soel curled in Joel's lap the whole time, and it is somehow not less intimate for having a spirit cat as a chaperone — if anything, it feels more like the family the two of you are quietly building, one uninvited guest at a time."},{"speaker":"Joel","text":"\"I asked to stand beside you while you found out why you were here,\" he says, one hand still absently scratching behind Soel's ears. \"I am asking if you want me beside you for the rest of it too. Both of us, apparently.\""},{"speaker":"San","text":"\"Both of you,\" you say. \"I would not have it any other way.\""}]},{"id":"mb-aisyah_hangout","kind":"bonding","group":"Aisyah","title":"A Bad Hand of Cards","icon":"🃏","scenes":[{"speaker":"Narrator","text":"Aisyah produces a deck of cards from somewhere you genuinely do not want to ask about and deals without being invited, which is very on-brand for her."},{"speaker":"Aisyah","text":"\"You are terrible at this,\" she says, not unkindly, watching you lose track of your own hand for the third time. \"You were terrible at this in the old world too. Some things survive the crossing between dimensions, apparently. Your card sense is not one of the good ones.\""},{"speaker":"San","text":"\"I am playing a long game,\" you say. \"A very long game. You will not understand the strategy until it is too late.\""},{"speaker":"Aisyah","text":"\"You are bluffing with a pair of twos,\" she says, and lays down her own hand, and takes your gold with the specific satisfaction of an older sister who has been doing this since before you could count. \"I taught you to trade. I did not teach you to lie about it convincingly. My mistake, evidently.\""},{"speaker":"Narrator","text":"She deals again anyway, without being asked, because losing to your sister at cards by firelight turns out to be one of the more normal things that has happened to you in a very long time, and neither of you says out loud how much that normalcy is worth."}],"theme":"theme-act2-water","motifs":["clock","beam"],"who":"Aisyah","minAffinity":150,"alt":null},{"id":"mb-aisyah_business","kind":"bonding","group":"Aisyah","title":"What She Left Behind","icon":"📒","scenes":[{"speaker":"Narrator","text":"You ask her, finally, about the life before this one — not the trading, the real before, the chalk and the marked homework and the decades of secondary school math classes she never talks about unless she is teaching you something practical with it."},{"speaker":"Aisyah","text":"\"I taught math for most of my working life,\" she says, and there is no performance in it, none of the sharp-tongued bravado she usually wears. \"Secondary school. Decades of it. The reselling — the actual trading you know me for — that only started five, six years before all of this. I saw where the trend was going and I followed it, same as anyone smart enough to notice. It was never the whole story. It was just the newest chapter.\""},{"speaker":"San","text":"\"Do you miss the classroom?\" you ask, and it feels like the first genuinely careful question you have ever asked her."},{"speaker":"Aisyah","text":"\"Every day,\" she admits. \"Not the marking, god, never the marking. The teaching. Watching a student who insisted they were bad at math finally see the shape of an equation click into place. I do not get to build understanding in people anymore. I get to keep them alive instead. Different kind of lesson.\""},{"speaker":"Narrator","text":"She is quiet for a moment, turning something over."},{"speaker":"Aisyah","text":"\"Though I suppose I am still teaching, if I am honest,\" she says. \"Just slower. With knives instead of chalk. You. Senedra and Zaki, in their own ways. I do not think the skill ever really left, just the classroom.\""},{"speaker":"San","text":"\"That counts,\" you tell her. \"That counts more than the classroom ever did.\""},{"speaker":"Narrator","text":"She does not answer, but she does not deflect either, which from Aisyah is its own kind of agreement. She keeps a small notebook in her pack now, the kind a teacher grades in. You have seen her write in it, some nights, when she thinks no one is watching."}],"theme":"theme-act2-water","motifs":["dawn","mirror"],"who":"Aisyah","minAffinity":600,"alt":null},{"id":"mb-eliz_family","kind":"bonding","group":"Eliz","title":"What She Carries","icon":"🕊️","scenes":[{"speaker":"Narrator","text":"You ask her, gently, how she is really doing — not the healer-checking-in question, the real one. It is a harder question to ask than it should be, given how much distance has sat between the two of you for so long, and you both know it."},{"speaker":"Eliz","text":"\"We have not talked like this in a long time,\" she says, not unkindly, just honestly, turning the question over like she is checking it for sharp edges before deciding it is safe to answer. \"I do not think that is anyone's fault, exactly. We just fit different lives. You know that better than most.\""},{"speaker":"San","text":"\"I know,\" you admit. \"I have never been sure how to close that kind of distance. I am not sure I am closing it now. I am just trying.\""},{"speaker":"Eliz","text":"\"That is enough to start with,\" she says, and something in her posture eases, just slightly. \"Everyone assumes the magic is the strange part of me. The textures, the colors, the way I perceive things no one else does. That part I have always had, even before all of this. I was already autistic in the old world. Aethon just gave the rest of you a word for what it looks like from the outside.\""},{"speaker":"San","text":"\"Was that hard? Growing up?\""},{"speaker":"Eliz","text":"\"Not at first,\" she says. \"I idolized you, honestly, when I was small. You were the exciting relative, the one who felt like proof that a life could look different than the one right in front of me. Then I turned sixteen and something in me just — changed. I stopped being happy-go-lucky. I wanted space. Freedom. Time that belonged only to me. I got harder to reach, and harder on myself too — convinced sometimes that the world just did not like me very much, that socializing was a language everyone else had been handed and I had to translate from scratch every time.\""},{"speaker":"Narrator","text":"You recognize the shape of that even if you never lived it exactly the same way — the particular exhaustion of being expected to perform a version of normal that was never actually built for you."},{"speaker":"Eliz","text":"\"My mother has her own story, if you want it,\" she offers, watching you carefully, gauging whether this is a door you actually want opened. \"She left home young — barely into her twenties, by her own account. Her first marriage ended when he cheated on her. She rebuilt herself after that, properly rebuilt — moved to Singapore, became someone sharper, more polished than the girl who left Brunei. Career woman. She met my father through work, out there. They were together a while before I came along. Shotgun marriage, if we are being honest about the timeline.\""},{"speaker":"San","text":"You listen, quiet, because this is clearly a story she has needed to tell someone for a long time and never quite had the right person to tell it to."},{"speaker":"Eliz","text":"\"Then the company they both worked for collapsed,\" she continues. \"My mother pulled herself out of the wreckage the way she always does. My father did not — he found the bottom of a bottle instead, and a lot of cigarettes. And then you and your mother moved into our house, around when you were applying to study in Singapore after the exam in Brunei did not go the way anyone hoped. I do not think that was the reason things ended. I think it was just the last weight on a bridge that was already failing. They separated when I was one. I do not remember any of it firsthand. I only have the story, passed down in pieces.\""},{"speaker":"Eliz","text":"\"My mother was Mez, before the magic changed her into Mezstorm,\" she adds, softer now. \"I lost a version of her and gained a different one, both real, both mine, and I am still learning how to hold both truths without one erasing the other. He is still my parent. That did not change. Only the shape of him did.\""},{"speaker":"San","text":"You do not say anything clever. You just listen, because this is clearly not a wound that needs a solution — it needs a witness."},{"speaker":"Eliz","text":"\"I am telling you all of this because you are family, and family should know the real story, not the healer-shaped version of it,\" she says, finally looking at you directly. \"I know we have been distant. Singapore moves differently than Brunei ever did, and so do the expectations that come with it, and I know you have never quite fit the shape people wanted you to be either. Maybe that is exactly why we drifted — too similar in the wrong way, both of us bad at performing what was expected. I do not know how to fix that in one conversation. I would like to try, though. Slowly.\""},{"speaker":"San","text":"\"Slowly,\" you agree. \"I would like that too. I am sorry it took this long for either of us to say so.\""}],"theme":"theme-act2-water","motifs":["horizon","mend"],"who":"Eliz","minAffinity":500,"alt":null},{"id":"mb-senedra_solitude","kind":"bonding","group":"Senedra","title":"The Quiet She Chose","icon":"🏹","scenes":[{"speaker":"Narrator","text":"You find her sitting apart from the others, not sulking, just still, the way she gets sometimes when the party's noise adds up to more than she wants to carry that day."},{"speaker":"Senedra","text":"\"You do not have to sit with me out of obligation,\" she says, without turning around, already knowing it is you by footstep alone. \"I am not lonely. I am just alone. There is a difference, even if most people do not believe me when I say it.\""},{"speaker":"San","text":"\"I believe you,\" you say, and sit anyway, a comfortable distance away, not crowding the quiet she clearly chose on purpose."},{"speaker":"Senedra","text":"\"I learned to track alone, mostly,\" she says, after a while, unprompted, which is rare for her. \"My mother taught me the paths, but the actual walking — that was mine. Hours of it. Days, sometimes. You learn to like your own company, or the silence eats you. I chose to like it.\""},{"speaker":"San","text":"\"Does the party ever feel like too much, after that?\""},{"speaker":"Senedra","text":"\"Sometimes,\" she admits. \"Not because I do not love you all. Because I spent so long being the only voice in my own head that a room full of other people's feels loud, even when it is kind. I am still learning how to let it in without flinching.\""},{"speaker":"Narrator","text":"She does not say more than that, and you do not push, and eventually she leans, just slightly, close enough that her shoulder rests against yours — not a big gesture, but from Senedra, it is practically a speech."}],"theme":"theme-act2-water","motifs":["candles","figures"],"who":"Senedra","minAffinity":200,"alt":null},{"id":"mb-senedra_family","kind":"bonding","group":"Senedra","title":"Before He Stopped Coming Back","icon":"🎖️","scenes":[{"speaker":"Narrator","text":"You ask about her family, carefully, since she has never offered it herself, and for a long moment you think she will simply decline the question the way she declines most things she has not decided to trust you with yet."},{"speaker":"Senedra","text":"\"My father had a reputation, before any of this,\" she says instead, finally, watching an arrow she is not actually fletching. \"Some people called him a bad boy. Some called him worse — a gangster, a hooligan. For a while, when I was very small, that edge seemed almost charming. Dangerous in a way that felt like an adventure instead of a warning.\""},{"speaker":"San","text":"\"What changed?\""},{"speaker":"Senedra","text":"\"An addiction took him,\" she says, plainly, not dressing it up. \"I never knew exactly what, only that he found something that mattered to him more than any of us did, and there was not room left for anything else once it had him. He would disappear for months at a time. Money went with him, every time — taken from my mother's savings, like providing for us mattered less than keeping his supply going.\""},{"speaker":"Narrator","text":"She says it evenly, the way you say something you have said to yourself so many times it has worn smooth, like a river stone. But her hands have gone still on the arrow, and you notice."},{"speaker":"Senedra","text":"\"My mother tried to salvage it every single time he came back,\" she continues. \"Aisyah. Though she was not always the sharp-eyed trader you know now — she was younger, and hope is its own kind of exhausting labor, and she did that labor over and over, believing each return might be the one that stuck.\""},{"speaker":"Senedra","text":"\"I was his favorite, before,\" she adds, quieter. \"I remember that clearly, and painfully — being chosen, being the one he noticed. And then watching that favor evaporate right along with everything else he was losing. One day he simply stopped coming back at all. No goodbye. No explanation. It took my mother years to even finalize the divorce, because you cannot divorce someone who will not show up long enough to end it properly.\""},{"speaker":"Senedra","text":"\"Zaki carries the same story, in his own way,\" she says. \"Different angle on it — he was never the favorite, so he lost less of that particular thing. We do not talk about it with each other much. We do not need to. Some things you can just recognize in a sibling without saying them out loud.\""},{"speaker":"Senedra","text":"\"I think that is why I learned to track,\" she continues. \"I could not track him. No one could. So I got very, very good at finding everyone else instead. It does not fix anything. It just means I am never the reason someone stays lost. And it means I am careful now, with being anyone's favorite. I know exactly what that costs when it is taken away.\""},{"speaker":"San","text":"\"You have found every path I have ever needed,\" you tell her. \"I do not think that is a coincidence.\""},{"speaker":"Senedra","text":"She almost smiles at that — not quite, but almost, which from her is its own kind of gratitude."}],"theme":"theme-act2-water","motifs":["phone","beam"],"who":"Senedra","minAffinity":700,"alt":null},{"id":"mb-zaki_family","kind":"bonding","group":"Zaki","title":"Checking His Pack","icon":"🎖️","scenes":[{"speaker":"Narrator","text":"You catch Zaki checking his pack again, the old nervous habit, except this time he keeps going long after there is anything left to check, and you realize it is not about the pack at all."},{"speaker":"Zaki","text":"\"I was not the favorite,\" he says, not looking up, hands still moving through the same three pockets over and over. \"Senedra was. So I had less of my father to begin with, which meant less got taken when things fell apart. Less is not nothing, though. What I remember most is the money disappearing — not really understanding why, as a kid, why there was suddenly nothing left, why my mom's face changed every time she checked her cards.\""},{"speaker":"San","text":"\"Your mom being Aisyah,\" you say, and he nods."},{"speaker":"Zaki","text":"\"Eventually she cut off his access to her money completely,\" Zaki continues. \"That felt like the real ending, more than any conversation ever could have been. He had an addiction — I do not know exactly what, we never talked about the specifics, just that he found something that mattered to him more than any of us did. There stopped being room for anything else once it had him. He would vanish for months. Then one day he just did not come back at all. No goodbye. Years of nothing after that, before the divorce was even final.\""},{"speaker":"Narrator","text":"He laughs, a little, at himself, but it does not quite land as a joke."},{"speaker":"Zaki","text":"\"So the pack-checking,\" he says. \"Everyone thinks it is nerves before a fight. It is not, really. I grew up somewhere money and people could just vanish overnight, no warning. So I learned to make sure of the things I actually could make sure of. Boots tied. Supplies counted. Small, controllable things, because the big ones never asked my permission before disappearing.\""},{"speaker":"San","text":"\"I do not think that is nervous,\" you tell him. \"I think that is love wearing a very practical disguise.\""},{"speaker":"Zaki","text":"He looks up at that, surprised, like no one has ever put it that way to him before. \"Yeah,\" he says, slowly. \"Yeah, maybe it is.\""},{"speaker":"Zaki","text":"\"My mom found happiness again, eventually,\" he adds, and this part of the story visibly sits easier in him. \"Years later. And I actually got a real father figure out of it — maybe because I never had as much invested in the first one to compare it against. I could just let the new one be what it was. Senedra holds it a little more carefully. She remembers more of the original to measure against. I got lucky, I think, in the worst possible way — I had less to lose, so I had more room left over to just accept something good when it finally showed up.\""}],"theme":"theme-act2-water","motifs":["clock","embers"],"who":"Zaki","minAffinity":700,"alt":null},{"id":"mb-zaki_oldworld","kind":"bonding","group":"Zaki","title":"The Old World, Between Fights","icon":"💪","scenes":[{"speaker":"Narrator","text":"Zaki asks, out of nowhere, what your life actually looked like before all of this — not the ADHD-productivity-app version, the real day-to-day of it. You find yourself telling him more than you meant to."},{"speaker":"San","text":"\"Freelance writing, mostly,\" you say. \"Chapters on an online story website, whenever I actually had readers waiting. Copywriting the rest of the time, for whoever was paying. Some weeks were fine. Some weeks I could not make myself start anything until 11pm and then I would write six hours straight in a panic. The usual.\""},{"speaker":"Zaki","text":"\"That sounds exhausting,\" he says, and there is real sympathy in it, not pity. \"I did the gig work, actually — odd jobs, whatever paid that week. Never anything that stuck. I think I was always looking for something that felt like it mattered, and none of it quite did. Writing sounds like it at least gave you that, some weeks.\""},{"speaker":"San","text":"\"Some weeks,\" you agree. \"The good ones. Did you have people?\" you ask. \"Friends, I mean. Before.\""},{"speaker":"Zaki","text":"\"A few,\" he says. \"Gym friends, mostly — the kind where you know their whole workout split and nothing about their actual life. I used to go most days. Not even for the gains, honestly. Just for somewhere to be that had a routine I could not talk myself out of.\""},{"speaker":"Narrator","text":"You laugh, because you understand that completely — the specific comfort of a place that does not care how your week has been, only that you showed up."},{"speaker":"San","text":"\"I miss having a routine like that,\" you admit. \"Something dumb and physical that did not require me to feel anything about it.\""},{"speaker":"Zaki","text":"\"We could build one here,\" Zaki says, brightening, like this is obvious. \"Sparring, every few days. Same time. No pressure, no big feelings required. Just showing up.\" He grins. \"I will even let you win sometimes. Rarely. But sometimes.\""},{"speaker":"San","text":"\"Deal,\" you say, and mean it more than the joke deserves."}],"theme":"theme-act2-water","motifs":["rings","clock"],"who":"Zaki","minAffinity":250,"alt":null},{"id":"mv-mem_locked_gate","kind":"vision","group":"Vision Machine","title":"The Locked Gate","icon":"🚪","scenes":[{"speaker":"Narrator","text":"You are sixteen, and the gate is locked again, and your mother is already at the window before you have even knocked."},{"speaker":"Mama","text":"\"Where were you? You said six.\""},{"speaker":"San","text":"\"It is six-fifteen, Mama.\""},{"speaker":"Narrator","text":"She lets you in without another word, but the porch light stays on an hour longer than it needs to, every single night after."}],"theme":"theme-act2-void","motifs":["doors","horizon"],"order":0},{"id":"mv-mem_every_call","kind":"vision","group":"Vision Machine","title":"Every Call Answered","icon":"📞","scenes":[{"speaker":"Narrator","text":"The phone rings twice before you even reach the bus stop, every single morning, the same number, the same three questions."},{"speaker":"Dad","text":"\"Did you eat? Do you have money? Text when you arrive.\""},{"speaker":"San","text":"\"Yes, yes, I will, Papa.\""},{"speaker":"Narrator","text":"You did not understand it then, how much of that was love wearing the only shape fear ever taught them to give it."}],"theme":"theme-act2-void","motifs":["phone","ledger"],"order":1},{"id":"mv-mem_aisyah_wedding","kind":"vision","group":"Vision Machine","title":"Aisyah’s Wedding Day","icon":"💍","scenes":[{"speaker":"Narrator","text":"She cries in the car beforehand, just once, quick, like she is embarrassed to be caught at it."},{"speaker":"Aisyah","text":"\"I am not sad,\" she says, before you can ask. \"I just did not think I would actually get here.\""},{"speaker":"San","text":"\"You got here,\" you tell her, fixing her veil. \"Whatever happens after, you got here.\""}],"theme":"theme-act2-void","motifs":["mend","dawn"],"order":2},{"id":"mv-mem_mez_marriage","kind":"vision","group":"Vision Machine","title":"Mezstorm’s Marriage, Once","icon":"💐","scenes":[{"speaker":"Narrator","text":"She looked happy, once. You have to remind yourself of that sometimes, now, looking back through everything that came after."},{"speaker":"Mez","text":"\"I think this is actually going to work,\" she says, young, certain, holding a bouquet she picked herself."},{"speaker":"Narrator","text":"It is not a lie, exactly, the way it ends later. It is just not the whole story either. Nothing ever is, at the beginning."}],"theme":"theme-act2-void","motifs":["dawn","clock"],"order":3},{"id":"mv-mem_mez_left","kind":"vision","group":"Vision Machine","title":"The Day Mez Left","icon":"🌧️","scenes":[{"speaker":"Narrator","text":"There are no boxes, not really. There is just Mez, at the door, two sons already gone ahead with their father, and a silence that does not know how to end itself."},{"speaker":"Mez","text":"\"Take care of yourself,\" she says, and it sounds like an apology for something much larger than the sentence itself."},{"speaker":"San","text":"\"You too,\" you say, and do not know, yet, how long it will actually take her to mean it."}],"theme":"theme-act2-void","motifs":["rings","doors"],"order":4},{"id":"mv-mem_village_well","kind":"vision","group":"Vision Machine","title":"The Village Well","icon":"🪣","scenes":[{"speaker":"Narrator","text":"Joel is eight, carrying water twice his own weight, and nobody around him thinks that is unusual, because it isn’t."},{"speaker":"Young Joel","text":"\"Almost home,\" he tells himself, out loud, the way children do when the walk is long and the arms are tired."},{"speaker":"Narrator","text":"He will do this walk hundreds more times before he is grown. He will never once complain about it where his mother can hear."}],"theme":"theme-act2-void","motifs":["road","water"],"order":5},{"id":"mv-mem_shared_shoes","kind":"vision","group":"Vision Machine","title":"Shared Shoes","icon":"👞","scenes":[{"speaker":"Narrator","text":"There is one good pair between the three brothers, and a schedule nobody wrote down but everyone somehow knew."},{"speaker":"Young Joel","text":"\"Your turn tomorrow,\" he tells his brother, already used to it, already unbothered in the specific way poverty teaches a child to be unbothered."},{"speaker":"Narrator","text":"He does not remember resenting it. He remembers being fast, and careful, and grateful there was a pair at all."}],"theme":"theme-act2-void","motifs":["fog","mobile"],"order":6},{"id":"mv-mem_movie_hated","kind":"vision","group":"Vision Machine","title":"The Movie They Both Hated","icon":"🎬","scenes":[{"speaker":"Joel","text":"\"This is the worst thing I have ever watched,\" Joel whispers, forty minutes in, entirely serious."},{"speaker":"San","text":"\"Then why did you pick it?\""},{"speaker":"Joel","text":"\"I did not know! The poster looked good!\""},{"speaker":"Narrator","text":"You do not remember a single plot point, years later. You remember laughing the whole way home about how bad it was."}],"theme":"theme-act2-void","motifs":["beam","rings"],"order":7},{"id":"mv-mem_cant_afford_dinner","kind":"vision","group":"Vision Machine","title":"A Dinner Neither Could Afford","icon":"🍽️","scenes":[{"speaker":"Narrator","text":"You split one dessert between you, technically two spoons, mostly just an excuse to sit somewhere nice a little longer."},{"speaker":"San","text":"\"We really should not have ordered this.\""},{"speaker":"Joel","text":"\"Worth it,\" Joel says, already reaching for a second bite before you can. \"Absolutely worth it.\""}],"theme":"theme-act2-void","motifs":["cracks","rings"],"order":8},{"id":"mv-mem_birthday_surprise","kind":"vision","group":"Vision Machine","title":"Her Birthday, His Surprise","icon":"🎂","scenes":[{"speaker":"Narrator","text":"He is a terrible liar about it for a week beforehand, and you let him think he pulled it off anyway."},{"speaker":"Joel","text":"\"Surprise,\" Joel says, entirely unnecessary, since you have known for days."},{"speaker":"San","text":"\"I had no idea,\" you tell him, and mean the kindness of it, if not the literal truth."}],"theme":"theme-act2-void","motifs":["leaves","embers"],"order":9},{"id":"mv-mem_new_year","kind":"vision","group":"Vision Machine","title":"New Year, Just the Two of Them","icon":"🎆","scenes":[{"speaker":"Narrator","text":"No party, no crowd — just the two of you on a rooftop somewhere, watching a sky neither of you paid to see."},{"speaker":"Joel","text":"\"Any resolutions?\" Joel asks, half-joking."},{"speaker":"San","text":"\"Just this,\" you say. \"More of exactly this.\""}],"theme":"theme-act2-void","motifs":["beam","figures"],"order":10},{"id":"mv-mem_first_fight","kind":"vision","group":"Vision Machine","title":"Their First Real Fight","icon":"💢","scenes":[{"speaker":"Narrator","text":"It is about something small, the way first fights usually are — a missed message, an assumption neither of you checked."},{"speaker":"Joel","text":"\"I just wish you had told me,\" Joel says, frustrated but not unkind about it."},{"speaker":"San","text":"\"I should have,\" you admit. \"I am sorry.\""},{"speaker":"Narrator","text":"It does not last the night. Neither of you is built for a cold war, even this early on."}],"theme":"theme-act2-void","motifs":["dawn","phone"],"order":11},{"id":"mv-mem_deadline","kind":"vision","group":"Vision Machine","title":"The Deadline That Never Ends","icon":"💻","scenes":[{"speaker":"Narrator","text":"Midnight, again, the office mostly empty, the same report open for the third revision."},{"speaker":"San","text":"\"I am starting to think this deadline is a metaphor,\" you mutter, to no one, at your desk."},{"speaker":"Narrator","text":"It is not a metaphor. It is just Tuesday."}],"theme":"theme-act2-void","motifs":["clock","office"],"order":12},{"id":"mv-mem_robin_bad_day","kind":"vision","group":"Vision Machine","title":"Robin’s Office, A Bad Day","icon":"📋","scenes":[{"speaker":"Narrator","text":"Robin is short with everyone that afternoon, snapping over nothing, and nobody in the office says a word about why."},{"speaker":"San","text":"\"Rough day,\" you say to a coworker, quiet, in the hallway after."},{"speaker":"Narrator","text":"You do not know yet what is actually happening at his house. Nobody does. Not for a long while."}],"theme":"theme-act2-void","motifs":["office","pillars"],"order":13},{"id":"mv-mem_hotel_day","kind":"vision","group":"Vision Machine","title":"Just the Two of Them, A Whole Day","icon":"🏨","scenes":[{"speaker":"Narrator","text":"No plans, no schedule — just a hotel room, breakfast in bed, and an entire day neither of you had to share with anyone else."},{"speaker":"Joel","text":"\"We should do this more,\" Joel says, unhurried, meaning it."},{"speaker":"San","text":"\"We should,\" you agree, already knowing how rarely life actually allows it."}],"theme":"theme-act2-void","motifs":["cracks","leaves"],"order":14},{"id":"mv-mem_joel_daughter_hair","kind":"vision","group":"Vision Machine","title":"Learning, Badly, To Braid","icon":"🎀","scenes":[{"speaker":"Narrator","text":"Joel’s hands are too big for this, and he knows it, and his daughter waits anyway, patient in the way small children are patient with people they trust."},{"speaker":"Young Joel","text":"\"Almost got it,\" he says, for the fourth time, clearly not close."},{"speaker":"Narrator","text":"She laughs at the lopsided result in the mirror. He laughs too. Neither of them minds that it is crooked."}],"theme":"theme-act2-void","motifs":["clock","mobile"],"order":15},{"id":"mv-mem_daughter_phone_call","kind":"vision","group":"Vision Machine","title":"A Phone Call, Her Voice","icon":"📱","scenes":[{"speaker":"Narrator","text":"The call is short, the connection worse than usual, but her voice comes through clear enough for what matters."},{"speaker":"Young Joel","text":"\"Papa, guess what happened at school today,\" she says, already talking before he can even say hello properly."},{"speaker":"Narrator","text":"He listens to every word of it, twice as long as the story actually takes to tell."}],"theme":"theme-act2-void","motifs":["phone","rings"],"order":16},{"id":"mv-mem_mama_table","kind":"vision","group":"Vision Machine","title":"Mama’s Table, Full","icon":"🍚","scenes":[{"speaker":"Narrator","text":"Too much food, as always, Mama insisting everyone take seconds before anyone has finished firsts."},{"speaker":"Mama","text":"\"Eat more. You are both too thin.\""},{"speaker":"Joel","text":"\"We are not thin, Mama.\""},{"speaker":"Mama","text":"\"Eat more anyway.\""}],"theme":"theme-act2-void","motifs":["figures","dawn"],"order":17},{"id":"mv-mem_parents_dinner","kind":"vision","group":"Vision Machine","title":"Dinner, Just the Three of Them","icon":"🍲","scenes":[{"speaker":"Narrator","text":"An ordinary weeknight, nothing special about the meal, everything special about who is at the table."},{"speaker":"Dad","text":"\"How was your week?\""},{"speaker":"San","text":"\"Busy. Good, though.\""},{"speaker":"Narrator","text":"Nobody says anything more meaningful than that. It does not need to be more meaningful than that."}],"theme":"theme-act2-void","motifs":["mend","dawn"],"order":18}];
const WALK_LINES = ["Neither of you says much. You do not need to. Some days that is the entire point of it.","\"You looked like you needed this,\" Joel says, simple, not making it into a bigger thing than it is.","He matches your pace without being asked to, the way he always has.","For a while, you are not the guild leader, or a hunter of dragons, or anyone’s aunt. You are just walking, with Joel, and that is enough.","\"Still here,\" Joel says, quiet, when the silence stretches long. It is not a question. It never really is, with him.","The list of everything waiting for you does not go anywhere. It can wait a little longer than it thinks it can."];
